  this._element.style.display = 'block'
  this._element.removeAttribute('aria-hidden')
  this._element.setAttribute('aria-modal', true)
  this._element.setAttribute('role', 'dialog')
  this._element.scrollTop = 0

  if (modalBody) {
    modalBody.scrollTop = 0
  }

  // Manage focus wrap for Shift+Tab/Tab within modal
  const firstEl = document.getElementById('confirm-close')
  const lastEl = document.getElementById('confirm-delete')
  if (firstEl && lastEl) {
    this._firstKeydownListener = e => {
      if (e.shiftKey && e.key === 'Tab') {
        e.preventDefault()
        lastEl.focus()
      }
    }
    this._lastKeydownListener = e => {
      if (!e.shiftKey && e.key === 'Tab') {
        e.preventDefault()
        firstEl.focus()
      }
    }
    firstEl.addEventListener('keydown', this._firstKeydownListener)
    lastEl.addEventListener('keydown', this._lastKeydownListener)
  }

  if (isAnimated) {
    reflow(this._element)
  }

  this._element.classList.add(CLASS_NAME_SHOW)

  if (this._config.focus) {
    this._enforceFocus()
  }

  const transitionComplete = () => {
    if (this._config.focus) {
      this._element.focus()
    }

    this._isTransitioning = false
    EventHandler.trigger(this._element, EVENT_SHOWN, {
      relatedTarget
    })
  }

  this._queueCallback(transitionComplete, this._dialog, isAnimated)
}

