    const firstEl = document.getElementById('confirm-close')
    if (firstEl) {
      firstEl.removeEventListener('keydown', this._firstKeydownListener)
    }
  }
  if (this._lastKeydownListener) {
    const lastEl = document.getElementById('confirm-delete')
    if (lastEl) {
      lastEl.removeEventListener('keydown', this._lastKeydownListener)
    }
    this._firstKeydownListener = null
    this._lastKeydownListener = null
  }

  this._isTransitioning = false
  this._backdrop.hide(() => {
    document.body.classList.remove(CLASS_NAME_OPEN)
    this._resetAdjustments()
    this._scrollBar.reset()
    EventHandler.trigger(this._element, EVENT_HIDDEN)
  })
}
